000028 | 			setViewBean(request.getSession(), pensionBean(existing,
000029 | 				"同じフリガナと電話番号の既存データを読み込みました。内容を確認してから登録してください。",
000030 | 				true, request.getSession()));
000031 | 			return PENSION_JSP;
