000041 | 			setViewBean(request.getSession(), pensionBean(existing,
000042 | 				"権限が不足しています。変更を行う場合には\r\n推進役以上の方が変更してください。",
000043 | 				true, request.getSession()));
000044 | 			return PENSION_JSP;
000045 | 		}
000046 | 		repository.save(value, Integer.valueOf(staff.getStaffNo()));
000047 | 		setViewBean(request.getSession(), pensionBean(repository.createEmpty(staff), "登録終了！", false, request.getSession()));
