000061 | 	}
000062 | 
000063 | 	private File resolveDatabaseFile(ServletContext context) {
000064 | 		String overridePath = System.getProperty("n2nenkin.db.path");
000065 | 		if (overridePath != null && overridePath.trim().length() > 0) {
000066 | 			return new File(overridePath.trim()).getAbsoluteFile();
000067 | 		}
000068 | 		String directory = context.getRealPath("/WEB-INF/local-db");
000069 | 		if (directory == null) throw new IllegalStateException("Expanded deployment is required for local H2.");
