000078 | 	private void initializeDatabase(ServletContext context) throws Exception {
000079 | 		Connection connection = null;
000080 | 		try {
000081 | 			connection = dataSource.getConnection();
000082 | 			runScript(context, connection, "/WEB-INF/resources/db/schema.sql");
000083 | 			runScript(context, connection, "/WEB-INF/resources/db/data.sql");
000084 | 		} finally {
000085 | 			if (connection != null) connection.close();
000086 | 		}
000087 | 	}
000088 | 
000089 | 	private void runScript(ServletContext context, Connection connection, String path) throws Exception {
000090 | 		InputStream stream = context.getResourceAsStream(path);
000091 | 		if (stream == null) throw new IllegalStateException("Database resource not found: " + path);
000092 | 		Reader reader = null;
000093 | 		try {
000094 | 			reader = new InputStreamReader(stream, "UTF-8");
000095 | 			RunScript.execute(connection, reader);
000096 | 		} finally {
000097 | 			if (reader != null) reader.close(); else stream.close();
000098 | 		}
000099 | 	}
000100 | 
000101 | 	private void bindDataSource() throws NamingException {
000102 | 		InitialContext context = new InitialContext();
000103 | 		try { context.createSubcontext("jdbc"); } catch (NameAlreadyBoundException e) { }
000104 | 		for (int i = 0; i < JNDI_NAMES.length; i++) context.rebind(JNDI_NAMES[i], dataSource);
000105 | 	}
000106 | 
000107 | 	private void unbindDataSource() {
000108 | 		try {
000109 | 			Context context = new InitialContext();
000110 | 			for (int i = 0; i < JNDI_NAMES.length; i++) {
000111 | 				try { context.unbind(JNDI_NAMES[i]); } catch (NamingException e) { }
000112 | 			}
000113 | 		} catch (NamingException e) { }
000114 | 	}
000115 | 
000116 | 	private void shutdownDatabase(ServletContext context) {
000117 | 		if (dataSource == null) return;
000118 | 		Connection connection = null;
000119 | 		Statement statement = null;
000120 | 		try {
000121 | 			connection = dataSource.getConnection();
000122 | 			statement = connection.createStatement();
000123 | 			statement.execute("SHUTDOWN");
000124 | 		} catch (Exception e) {
000125 | 			context.log("H2 shutdown failed.", e);
000126 | 		} finally {
000127 | 			try { if (statement != null) statement.close(); } catch (Exception e) { }
000128 | 			try { if (connection != null) connection.close(); } catch (Exception e) { }
000129 | 		}
000130 | 	}
000131 | }
