000027 | public abstract class CommonBaseSelect extends CommonBase {
000028 | 
000029 | 	/** 検索結果List */
000030 | 	private List list = null;
000031 | 
000032 | 	/**
000033 | 	 * コンストラクタ
000034 | 	 * 
000035 | 	 * @param connection
000036 | 	 */
000037 | 	public CommonBaseSelect(Connection connection) {
000038 | 		super(connection);
000039 | 	}
000040 | 
000041 | 	/**
000042 | 	 * SQLのSELECT文を実行する。
000043 | 	 * 
000044 | 	 * @param sql ＳＱＬ文
000045 | 	 */
000046 | 	public void execute(String sql) throws SQLException{
000047 | 
000048 | 		Statement stmt = null;
000049 | 		ResultSet rs = null;
000050 | 
000051 | 		try {
000052 | 			stmt = getConnection().createStatement();
000053 | 			rs = stmt.executeQuery(sql);
000054 | 
000055 | 			//ＳＱＬ実行が正常終了したら、debug ログ出力
000056 | 			if(FWLog.isDebug()){
000057 | 				FWLog.debug(this.getClass(), sql);
000058 | 			}
000059 | 
000060 | 			setList(convertResultSetToList(rs));
000061 | 
000062 | 			if(getList() != null){
000063 | 				setCount(getList().size());
000064 | 			}
000065 | 
000066 | 		} catch (SQLException e) {
000067 | 			FWLog.error(sql);
000068 | 			throw e;
000069 | 
000070 | 		} finally {
000071 | 			if (rs != null) rs.close();
000072 | 			if (stmt != null) stmt.close();
000073 | 			rs = null;
000074 | 			stmt = null;
000075 | 		}
000076 | 	}
000077 | 
000078 | 	/**
000079 | 	 * 
000080 | 	 * ResultSetをList(Map)の配列に変換する。
000081 | 	 * 
000082 | 	 * @param	rs	ResultSet
000083 | 	 * @return ls	変換されたList(Map)形式のデータ
000084 | 	 */
000085 | 	private List convertResultSetToList(ResultSet rs) throws SQLException{
000086 | 
000087 | 		List ls = new ArrayList();
000088 | 			
000089 | 		while (rs.next()) {
000090 | 
000091 | 			Map map = new HashMap();
000092 | 			ResultSetMetaData rsmd = rs.getMetaData();
000093 | 
000094 | 			for(int i=1; i <= rsmd.getColumnCount(); i++){
000095 | 				String name = rsmd.getColumnName(i);
000096 | 				String str = rs.getString(name);
000097 | 
000098 | 				if(str == null){
000099 | 					map.put(name,"");
000100 | 				} else {
000101 | 					map.put(name,str.trim());
000102 | 				}
000103 | 			}
000104 | 
000105 | 			ls.add(map);
000106 | 		}
000107 | 
000108 | 		return ls;
000109 | 	}
