000128 |         String iso = toIsoDate(value);
000129 |         if (iso.length() == 0) {
000130 |             return "";
000131 |         }
000132 |         Date date = parseIso(iso, value);
000133 |         Calendar calendar = new GregorianCalendar();
000134 |         calendar.setTime(date);
000135 |         int lastDay = calendar.getActualMaximum(Calendar.DAY_OF_MONTH);
000136 |         return iso.substring(0, 8) + twoDigits(lastDay);
000137 |     }
