000144 |         result = result.replace('　', ' ');
000145 |         return result;
000146 |     }
000147 | 
000148 |     private static Era findEra(String token) {
000149 |         Era[] values = ERAS;
000150 |         for (int i = 0; i < values.length; i++) {
000151 |             if (values[i].code.equalsIgnoreCase(token) || values[i].name.equals(token)) {
000152 |                 return values[i];
000153 |             }
000154 |         }
000155 |         throw new IllegalArgumentException("未対応の元号です: " + token);
000156 |     }
000157 | 
000158 |     private static Era eraFor(Date date) {
000159 |         for (int i = ERAS.length - 1; i >= 0; i--) {
000160 |             if (!date.before(ERAS[i].start)) {
000161 |                 return ERAS[i];
000162 |             }
000163 |         }
000164 |         throw new IllegalArgumentException("明治元年より前の日付は和暦変換できません。");
000165 |     }
000166 | 
000167 |     private static String formatIso(int year, int month, int day, String original) {
000168 |         String iso = fourDigits(year) + "-" + twoDigits(month) + "-" + twoDigits(day);
000169 |         parseIso(iso, original);
000170 |         return iso;
000171 |     }
000172 | 
000173 |     private static Date parseIso(String value, String original) {
000174 |         SimpleDateFormat format = new SimpleDateFormat("yyyy-MM-dd", Locale.ROOT);
000175 |         format.setLenient(false);
000176 |         try {
000177 |             return format.parse(value);
000178 |         } catch (ParseException e) {
000179 |             throw invalid(original);
000180 |         }
000181 |     }
000182 | 
000183 |     private static String twoDigits(int value) {
000184 |         return value < 10 ? "0" + value : Integer.toString(value);
000185 |     }
000186 | 
000187 |     private static String twoOrMoreDigits(int value) {
000188 |         return value < 10 ? "0" + value : Integer.toString(value);
000189 |     }
000190 | 
000191 |     private static String fourDigits(int value) {
000192 |         String result = Integer.toString(value);
000193 |         while (result.length() < 4) {
000194 |             result = "0" + result;
000195 |         }
000196 |         return result;
000197 |     }
000198 | 
000199 |     private static IllegalArgumentException invalid(String value) {
000200 |         return new IllegalArgumentException("日付の形式または実在性が不正です: " + value);
000201 |     }
000202 | 
000203 |     private static final class Era {
000204 |         private final String code;
000205 |         private final String name;
000206 |         private final int baseYear;
000207 |         private final Date start;
000208 |         private final Date end;
000209 | 
000210 |         private Era(String code, String name, int baseYear, String start, String end) {
000211 |             this.code = code;
000212 |             this.name = name;
000213 |             this.baseYear = baseYear;
000214 |             this.start = parseIso(start, start);
000215 |             this.end = end == null ? null : parseIso(end, end);
000216 |         }
000217 |     }
000218 | }
