000030 | 		Calendar target = Calendar.getInstance();
000031 | 		target.setTime(date);
000032 | 		int year = target.get(Calendar.YEAR);
000033 | 		int month = target.get(Calendar.MONTH) + 1;
000034 | 		int day = target.get(Calendar.DAY_OF_MONTH);
000035 | 		String symbol;
