000038 | 		else if (!date.before(parseIso("1989-01-08"))) { symbol = "H"; eraYear = year - 1988; }
000039 | 		else if (!date.before(parseIso("1926-12-25"))) { symbol = "S"; eraYear = year - 1925; }
000040 | 		else if (!date.before(parseIso("1912-07-30"))) { symbol = "T"; eraYear = year - 1911; }
000041 | 		else if (!date.before(parseIso("1868-09-08"))) { symbol = "M"; eraYear = year - 1867; }
